def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Collect opponent and own moves compactly
    opp = [h[1] for h in history]
    mine = [h[0] for h in history]

    # Count cooperation/defection
    opp_c = 0
    for a in opp:
        if a == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / n

    last_opp = opp[-1]
    last_mine = mine[-1]

    # Late-game exploitation window
    remaining = 100 - n

    # Tail run length of opponent's last action
    tail = 0
    for a in reversed(opp):
        if a == last_opp:
            tail += 1
        else:
            break

    # Tail run of mutual cooperation
    tail_cc = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C' and mine[i] == 'C':
            tail_cc += 1
        else:
            break

    # Very short horizon: start cooperative, mirror early defection
    if n == 1:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Strong retaliate against sustained defection
    if last_opp == 'D':
        if tail >= 3:
            return 'D'
        if opp_rate > 0.45:
            return 'D'
        # isolated defection in a cooperative match - forgive often
        if tail_cc >= 3 and remaining > 4:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        if opp_rate < 0.2 and remaining > 6:
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last
    # If opponent historically very cooperative, lock into CC but exploit late
    if opp_rate > 0.85:
        if remaining <= 1:
            return 'D'
        if remaining <= 3 and rng.random() < 0.35:
            return 'D'
        # very occasional probe when we've been perfectly cooperating
        if tail_cc >= 8 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Moderately cooperative opponent: cooperate, occasional test
    if opp_rate > 0.5:
        if remaining <= 1:
            return 'D'
        if remaining <= 3 and opp_rate > 0.7 and rng.random() < 0.4:
            return 'D'
        if last_mine == 'D' and tail_cc == 0:
            # re-establish cooperation
            return 'C'
        if tail_cc >= 5 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent mixes: be stingy with cooperation, punish defection
    if opp_rate > 0.3:
        if tail_cc >= 2:
            # locked in cooperation with a mixer - keep it but probe rarely
            if rng.random() < 0.06:
                return 'D'
            return 'C'
        if last_mine == 'D':
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Mostly defecting opponent. Defect to minimize losses.
    # Rare cooperative probes when opponent has softened.
    if last_opp == 'C' and tail >= 1:
        # Opponent just cooperated - reward
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    if opp_rate < 0.1:
        # near-constant defector: probe occasionally to invite cooperation
        if n % 17 == 0:
            return 'C'
        return 'D'

    # mild mixer among defectors
    if rng.random() < 0.15:
        return 'C'
    return 'D'
